  assert.equal(createHash('sha256').update(current).digest('hex'),pin.after);
  assert.equal(pin.beforeText,execFileSync('git',['show',pins.baseline+':'+file],{encoding:'utf8',maxBuffer:8*1024**2}).replaceAll('\r\n','\n'));
